}

class _$fileName$State extends State<$fileName$> with AutomaticKeepAliveClientMixin{


  var initialIndex = 0;

  late var items = <Tuple2<Tab, Widget>>[
    Tuple2(Tab(text: "选项1"), buildPage()),
    Tuple2(Tab(text: "选项2"), buildPage1()),
    Tuple2(Tab(text: "选项2"), buildPage2()),
  ];

  @override
  Widget build(BuildContext context) {
    super.build(context);

    return MaterialApp(
      home: DefaultTabController(
        initialIndex: initialIndex,
        length: items.length,
        child: Scaffold(
          appBar: AppBar(
            bottom: TabBar(
              tabs: items.map((e) => e.item1).toList(),
            ),
            title: Text('$widget'),
          ),
          body: TabBarView(
            children: items.map((e) => e.item2).toList(),
          ),
        ),
      ),
    );
  }

  @override
  bool get wantKeepAlive => true;

  Widget buildPage() {
    return SafeArea(
      child: CustomScrollView(
        slivers: <Widget>[
          Column(
            children: [
              Container(
                height: 500,
                width: double.infinity,
                color: ColorExt.random,
                padding: EdgeInsets.all(8),
                child: Wrap(
                  spacing: 8,
                  runSpacing: 8,
                  children: [
                    ElevatedButton(onPressed: (){
                        print("onPressed");
                    }, child: Text("Iterable"),),
                  ],
                ),
              )
            ],
          ),
        ].map((e) => SliverToBoxAdapter(child: e)).toList(),
      ),
    );
  }

  Widget buildPage1() {
    return SafeArea(
      child: CustomScrollView(
        slivers: <Widget>[
          Column(
            children: [
              Container(
                height: 500,
                color: ColorExt.random,

              )
            ],
          ),
        ].map((e) => SliverToBoxAdapter(child: e)).toList(),
      ),
    );
  }

  Widget buildPage2() {
    return SafeArea(
