class $fileName$ extends ConsumerStatefulWidget {

    /// 路由名称
  static String routeName = '$fileName$';

  /// 路由
  static final route = GoRoute(
    name: routeName,
    path: '/' + routeName,
    pageBuilder: (context, state) => MaterialPage(
      fullscreenDialog: true,
      child: $fileName$(),
    ),
  );

  const $fileName$({
    super.key,
  });

  @override
  ConsumerState<ConsumerStatefulWidget> createState() => _$fileName$State();
}

class _$fileName$State extends ConsumerState<$fileName$>
    with AutomaticKeepAliveClientMixin, _PageBuilder {
  @override
  _$fileName$State get state => this;

  @override
  bool get wantKeepAlive => true;

  /// 跳转页面并接收返回值
  void pickXXX() async {
    final result = await ref.router.pushRoutable<String>(
      const ExamplePage(
        requiredValue: '必传参数',
        model: AuthTokenVo(
          accessToken: 'AAA',
          refreshToken: 'RRR',
          expiration: 1,
        ),
      ),
    );
  }
}


mixin _PageBuilder on ConsumerState<$fileName$> {
  _$fileName$State get state;

  @override
  Widget build(BuildContext context) {
    // 调用 AutomaticKeepAliveClientMixin.build
    super.build(context);

    return Scaffold(
      backgroundColor: Colors.yellowAccent,
      appBar: AppBar(
        title: Text("$fileName$"),
      ),
      body: ListView(
        padding: const EdgeInsets.all(16),
        children: [
          ElevatedButton(
            onPressed: () async {
              state.pickXXX();
            },
            child: const Text('带参跳转并接收返回值'),
          ),
          Text('返回值:'),
        ],
      ),
    );
  }
}

